/** qlint contract proposal v0.1. Provider-neutral; no model or network dependency. */
export type Id = string;
export type JsonPrimitive = string | number | boolean | null;
export type Json = JsonPrimitive | Json[] | { [key: string]: Json };

export interface StageSpec {
  id: Id;
  /** Prerequisite stages; forms a DAG, not a total ordering. */
  after: Id[];
}
export interface FieldSpec {
  id: Id;
  /** Non-root JSON Pointer into an immutable, time-bounded snapshot. */
  pointer: string;
  valueType: "string" | "number" | "integer" | "boolean" | "array" | "object";
  nullable: boolean;
  availableFrom: Id;
  role: "evidence" | "policy" | "target" | "metadata";
  derivedFrom: Id[];
  sensitivity: "public" | "internal" | "restricted";
}
export interface StateContract {
  id: Id;
  stages: StageSpec[];
  fields: FieldSpec[];
}
export interface OptionSpec { id: Id; description: string }
export type OutputSpec =
  | { kind: "boolean"; criteria: { true: string; false: string } }
  | {
      kind: "categorical";
      selection: "partition" | "best_fit";
      options: OptionSpec[];
      /** A real content category, not the same thing as missing evidence. */
      fallbackOptionId?: Id;
      /** Natural-language tie resolution; screened, not statically proven. */
      tieBreak?: string;
    }
  | {
      kind: "ordinal";
      axis: string;
      /** List order is ascending; each description must be self-contained. */
      levels: OptionSpec[];
    };
export interface QuestionSpec {
  id: Id;
  revision: number;
  mode: "extract" | "interpret" | "predict";
  instructions: string;
  /** Every listed field is required for this v0.1 contract. */
  inputs: Id[];
  /** Kept orthogonal to mode; policy documents are also projected inputs. */
  policyRefs: Id[];
  applicability: string;
  /** Define what counts as evidence, including negative evidence. */
  evidenceBoundary: string;
  missingInput: "abstain";
  insufficientEvidence: "abstain";
  /** Metadata only; its actual value MUST NOT enter a prediction payload. */
  prediction?: { targetRef: Id; horizon: string };
  output: OutputSpec;
}
export interface GateSpec {
  purpose: "applicability" | "evidence";
  questionId: Id;
  /** p <= falseAtMost: false; p >= trueAtLeast: true; otherwise undecided. */
  falseAtMost: number;
  trueAtLeast: number;
}
export interface BindingSpec {
  questionId: Id;
  atStage: Id;
  profile: "feature" | "monitor" | "router" | "judge";
  gates: GateSpec[];
  onIndeterminate: "abstain";
}
export interface QuestionSuite {
  schemaVersion: "0.1";
  id: Id;
  state: StateContract;
  questions: QuestionSpec[];
  /** v0.1: exactly one binding per question in an executable suite. */
  bindings: BindingSpec[];
}

export interface PlanFieldProjection {
  fieldId: Id;
  pointer: string;
  valueType: FieldSpec["valueType"];
  nullable: boolean;
  /** Targets are never projected; the type excludes that role. */
  role: "evidence" | "policy" | "metadata";
  sensitivity: FieldSpec["sensitivity"];
  /** Redaction happens at the value boundary; the plan records the intent. */
  handling: "verbatim";
}
export interface PlanGate {
  purpose: GateSpec["purpose"];
  questionId: Id;
}
export interface PlanQuestion {
  questionId: Id;
  atStage: Id;
  profile: BindingSpec["profile"];
  mode: QuestionSpec["mode"];
  outputKind: OutputSpec["kind"];
  gates: PlanGate[];
  inputs: PlanFieldProjection[];
  /** Approved policy documents travel separately from evidence inputs. */
  policyRefs: PlanFieldProjection[];
  redaction: {
    policy: "explicit-projection-v0.1";
    excludedFieldIds: Id[];
    restrictedFieldIds: Id[];
    note: string;
  };
  limits: {
    maxBytes?: number;
    maxTokens?: number;
    rationale: string;
  };
}
/** Immutable, digest-bound execution plan produced by `qlint inspect`. */
export interface ExecutionPlan {
  schemaVersion: "0.1";
  kind: "qlint.execution-plan";
  tool: { name: "qlint"; version: string };
  provider: { name: "replay"; network: false };
  suite: { id: Id; digest: string };
  questions: PlanQuestion[];
  requestCount: number;
  maxRequests: number;
  notes: string[];
  /** sha256 over the plan content without this field. */
  digest: string;
}
export interface ProjectedPayload {
  questionId: Id;
  atStage: Id;
  inputs: Record<Id, Json>;
  policyRefs: Record<Id, Json>;
}
export interface ProjectionProblem {
  fieldId: Id;
  kind: "type_mismatch" | "target_role" | "unknown_field";
  message: string;
}
export type ProjectionOutcome =
  | { status: "projected"; payload: ProjectedPayload; requestDigest: string }
  | { status: "abstained"; reason: "missing_input" | "null_value"; fieldIds: Id[] }
  | { status: "invalid"; problems: ProjectionProblem[] };
export interface RecordedResponse {
  requestDigest: string;
  /** The raw provider response, kept opaque in this bundle. */
  response: Json;
}
export interface ReplayResult {
  caseId: Id;
  questionId: Id;
  status: "replayed" | "abstained" | "invalid" | "not_run";
  requestDigest?: string;
  payload?: ProjectedPayload;
  response?: Json;
  reason?: string;
  problems?: ProjectionProblem[];
}
export interface RunReport {
  schemaVersion: "0.1";
  kind: "qlint.run-report";
  mode: "replay";
  tool: { name: "qlint"; version: string };
  planDigest: string;
  suite: { id: Id; digest: string };
  results: ReplayResult[];
  summary: {
    cases: number;
    questions: number;
    replayed: number;
    abstained: number;
    invalid: number;
    notRun: number;
    requestsSent: number;
  };
  notExecuted: string[];
  /** sha256 over the report content without this field. */
  digest: string;
}
export type DiagnosticBasis = "static_proof" | "model_signal" | "empirical_witness";
export type Severity = "error" | "warning" | "info";
export type Evidence =
  | { kind: "contract_ref"; pointer: string }
  | { kind: "model_response"; runId: Id; answerId: Id; modelProbability?: number }
  | {
      kind: "paired_case";
      beforeCaseId: Id;
      afterCaseId: Id;
      transformId: Id;
      transformReview: "human_reviewed" | "unreviewed";
    }
  | { kind: "metric"; name: string; value: number; sampleSize: number; unit: string };
/**
 * A reported location. `pointer` always refers to the input document.
 * CLI tools add `file`/`line`/`column` after resolving the pointer against
 * the original text; `line` and `column` are 1-based. Library callers that
 * never see source text leave them absent.
 */
export interface DiagnosticLocation {
  pointer: string;
  file?: string;
  line?: number;
  column?: number;
}
export interface Diagnostic {
  ruleId: string;
  questionId?: Id;
  severity: Severity;
  basis: DiagnosticBasis;
  message: string;
  locations: DiagnosticLocation[];
  evidence: Evidence[];
}
export interface CheckCoverage {
  ruleId: string;
  status: "passed" | "flagged" | "unknown" | "not_run" | "not_applicable";
}
export interface Assessment {
  questionId: Id;
  status: "invalid" | "review_required" | "screened" | "inconclusive";
  coverage: CheckCoverage[];
  diagnostics: Diagnostic[];
  /** An explicit profile, not a universal correctness certificate. */
  profileId: Id;
}
export type ProbabilitySource =
  | "model_distribution"
  | "empirical_frequency"
  | "self_report";
export type Measurement =
  | { kind: "boolean"; representation: "distribution"; pTrue: number; probabilitySource: ProbabilitySource }
  | { kind: "boolean"; representation: "label"; value: boolean }
  | {
      kind: "categorical" | "ordinal";
      representation: "distribution";
      /** Stable option/level IDs; never silently key by presentation order. */
      distribution: Record<Id, number>;
      probabilitySource: ProbabilitySource;
    }
  | { kind: "categorical" | "ordinal"; representation: "label"; labelId: Id };
export interface RunProvenance {
  runId: Id;
  provider: string;
  requestedModel: string;
  resolvedModel?: string;
  providerRevision?: string;
  adapterVersion: string;
  specDigest: string;
  projectedStateDigest: string;
  ruleSetDigest: string;
  calibrationId?: string;
}
export type EvaluationResult =
  | { status: "answered"; measurement: Measurement; provenance: RunProvenance }
  | {
      status: "abstained";
      reason: "missing_input" | "insufficient_evidence" | "gate_uncertain";
      evidenceRefs: string[];
      provenance?: RunProvenance;
    }
  | { status: "not_applicable"; gateQuestionId: Id; provenance?: RunProvenance }
  | { status: "error"; code: string; message: string; retryable: boolean };
export interface BackendCapabilities {
  kinds: OutputSpec["kind"][];
  nativeDistribution: boolean;
  nativeAbstention: boolean;
  maxCategoricalOptions?: number;
  maxOrdinalLevels?: number;
  /** A declaration to be checked by adapter conformance tests. */
  questionIdsVisibleToModel?: boolean;
  siblingLevelDescriptionsVisible?: boolean;
}
export interface StaticReport {
  scope: "reference_static_checks_only";
  diagnostics: Diagnostic[];
  executedRuleIds: string[];
  notExecuted: string[];
}

/** A model can emit signals, never an authoritative Diagnostic or CI policy. */
export interface ModelScreenSignal {
  ruleId: string;
  questionId: Id;
  applicability: "applicable" | "not_applicable" | "unknown";
  evidenceSufficiency: "sufficient" | "insufficient" | "unknown";
  violation: Measurement;
  /** IDs must refer to fragments supplied by the parser; no invented quotes. */
  fragmentIds: Id[];
  provenance: RunProvenance;
}

state.plan_ts:
/**
 * Execution-plan construction (`qlint inspect`).
 *
 * The plan fixes exactly which state fields each question may send, keeps
 * policy references separate from evidence inputs, records redaction and
 * limits with their basis, and binds the whole content to a digest so
 * `qlint run` can detect edits. Pure: the caller supplies the suite.
 */
import type { ExecutionPlan, PlanFieldProjection, PlanQuestion, QuestionSuite } from "./contracts.js";
import { digestOf } from "./digest.js";

export class PlanError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PlanError";
  }
}

export interface PlanOptions {
  version: string;
  maxRequests?: number;
  maxBytes?: number;
  maxTokens?: number;
  allowRestricted?: boolean;
}

const PROJECTION_NOTE =
  "Only the fields listed for this question are projected. Every other declared field, including evaluation targets, is excluded; excludedFieldIds records that boundary.";

function limitRationale(options: PlanOptions): string {
  const parts: string[] = [];
  if (options.maxBytes === undefined && options.maxTokens === undefined) {
    parts.push("no payload-size estimate is computed at plan time because no state values exist yet; pass --max-bytes or --max-tokens to bind request size explicitly");
  } else {
    if (options.maxBytes !== undefined) parts.push(`maxBytes=${options.maxBytes} was provided by the caller, not derived from data`);
    if (options.maxTokens !== undefined) parts.push(`maxTokens=${options.maxTokens} was provided by the caller, not derived from data`);
  }
  return parts.join("; ");
}

export function buildPlan(suite: QuestionSuite, options: PlanOptions): ExecutionPlan {
  const fields = new Map(suite.state.fields.map(field => [field.id, field]));
  const bindings = new Map(suite.bindings.map(binding => [binding.questionId, binding]));
  const questions: PlanQuestion[] = [];

  for (const question of suite.questions) {
    const binding = bindings.get(question.id);
    if (!binding) throw new PlanError(`question ${question.id} has no execution binding`);

    const toProjection = (fieldId: string): PlanFieldProjection => {
      const field = fields.get(fieldId);
      if (!field) throw new PlanError(`question ${question.id} references unknown field ${fieldId}`);
      if (field.role === "target") throw new PlanError(`question ${question.id} references evaluation target ${fieldId}`);
      return {
        fieldId: field.id,
        pointer: field.pointer,
        valueType: field.valueType,
        nullable: field.nullable,
        role: field.role,
        sensitivity: field.sensitivity,
        handling: "verbatim",
      };
    };

    const inputs = question.inputs.map(toProjection);
    const policyRefs = question.policyRefs.map(toProjection);
    const used = new Set([...question.inputs, ...question.policyRefs]);
    const excludedFieldIds = suite.state.fields.filter(field => !used.has(field.id)).map(field => field.id);
    const restrictedFieldIds = [...inputs, ...policyRefs]
      .filter(projection => projection.sensitivity === "restricted")
      .map(projection => projection.fieldId);

    if (restrictedFieldIds.length > 0 && options.allowRestricted !== true) {
      throw new PlanError(
        `restricted fields require explicit approval via --allow-restricted: ${restrictedFieldIds.join(", ")}`,
      );
    }

    const redactionNote = options.allowRestricted === true && restrictedFieldIds.length > 0
      ? `${PROJECTION_NOTE} Restricted fields were explicitly approved for projection.`
      : PROJECTION_NOTE;

    const limits: PlanQuestion["limits"] = {
      ...(options.maxBytes === undefined ? {} : { maxBytes: options.maxBytes }),
      ...(options.maxTokens === undefined ? {} : { maxTokens: options.maxTokens }),
      rationale: limitRationale(options),
    };

    questions.push({
      questionId: question.id,
      atStage: binding.atStage,
      profile: binding.profile,
      mode: question.mode,
      outputKind: question.output.kind,
      gates: binding.gates.map(gate => ({ purpose: gate.purpose, questionId: gate.questionId })),
      inputs,
      policyRefs,
      redaction: { policy: "explicit-projection-v0.1", excludedFieldIds, restrictedFieldIds, note: redactionNote },
      limits,
    });
  }

  const requestCount = questions.length;
  const maxRequests = options.maxRequests ?? requestCount;
  if (maxRequests < requestCount) {
    throw new PlanError(`--max-requests ${maxRequests} is below the ${requestCount} requests this suite requires`);
  }

  const withoutDigest = {
    schemaVersion: "0.1" as const,
    kind: "qlint.execution-plan" as const,
    tool: { name: "qlint" as const, version: options.version },
    provider: { name: "replay" as const, network: false as const },
    suite: { id: suite.id, digest: digestOf(suite) },
    questions,
    requestCount,
    maxRequests,
    notes: [
      "provider replay: this plan is executed against recorded responses only; live providers are not implemented in this bundle",
      "gate runtime and adapter normalization are not part of plan execution",
      "the plan is digest-bound; qlint run refuses content whose digest does not match",
    ],
  };
  return { ...withoutDigest, digest: digestOf(withoutDigest) };
}

export function planDigest(plan: ExecutionPlan): string {
  const { digest: _digest, ...rest } = plan;
  return digestOf(rest);
}

export function verifyPlanDigest(plan: ExecutionPlan): boolean {
  return plan.digest === planDigest(plan);
}

state.projection_ts:
/**
 * Projection of one case snapshot onto one planned question.
 *
 * This is the last boundary before a payload could reach a model, so it
 * treats the plan as authoritative: only listed fields are read, policy
 * references stay separate from evidence inputs, missing and null values
 * become abstention (never an implicit false), and type violations stop the
 * request instead of being smoothed over.
 *
 * Pure: no filesystem, network, or environment access.
 */
import type { FieldSpec, Json, PlanFieldProjection, PlanQuestion, ProjectionOutcome, ProjectionProblem } from "./contracts.js";
import { digestOf } from "./digest.js";

export function decodePointerSegment(segment: string): string {
  return segment.replace(/~1/g, "/").replace(/~0/g, "~");
}

export function resolvePointer(state: Json, pointer: string): { found: true; value: Json } | { found: false } {
  const segments = pointer.split("/").slice(1).map(decodePointerSegment);
  let current: Json = state;
  for (const segment of segments) {
    if (Array.isArray(current)) {
      if (!/^(?:0|[1-9]\d*)$/.test(segment)) return { found: false };
      const index = Number(segment);
      if (index >= current.length) return { found: false };
      current = current[index]!;
      continue;
    }
    if (typeof current === "object" && current !== null) {
      const record = current as Record<string, Json>;
      if (!(segment in record)) return { found: false };
      current = record[segment]!;
      continue;
    }
    return { found: false };
  }
  return { found: true, value: current };
}

export function matchesDeclaredType(value: Json, valueType: FieldSpec["valueType"]): boolean {
  switch (valueType) {
    case "string": return typeof value === "string";
    case "number": return typeof value === "number";
    case "integer": return typeof value === "number" && Number.isInteger(value);
    case "boolean": return typeof value === "boolean";
    case "array": return Array.isArray(value);
    case "object": return typeof value === "object" && value !== null && !Array.isArray(value);
  }
}

export function projectQuestion(question: PlanQuestion, state: Json): ProjectionOutcome {
  const inputs: Record<string, Json> = {};
  const policyRefs: Record<string, Json> = {};
  const missing: string[] = [];
  const nulls: string[] = [];
  const problems: ProjectionProblem[] = [];

  const collect = (projections: PlanFieldProjection[], target: Record<string, Json>): void => {
    for (const projection of projections) {
      // The plan type and schema already exclude targets. Widening the role
      // here is deliberate defense in depth for unvalidated hand-made plans.
      const role: string = projection.role;
      if (role === "target") {
        problems.push({
          fieldId: projection.fieldId,
          kind: "target_role",
          message: `${projection.fieldId} is an evaluation target and must not be projected`,
        });
        continue;
      }
      const resolved = resolvePointer(state, projection.pointer);
      if (!resolved.found) {
        missing.push(projection.fieldId);
        continue;
      }
      if (resolved.value === null) {
        if (projection.nullable) {
          target[projection.fieldId] = null;
        } else {
          nulls.push(projection.fieldId);
        }
        continue;
      }
      if (!matchesDeclaredType(resolved.value, projection.valueType)) {
        problems.push({
          fieldId: projection.fieldId,
          kind: "type_mismatch",
          message: `${projection.fieldId} has a value that is not ${projection.valueType}`,
        });
        continue;
      }
      target[projection.fieldId] = resolved.value;
    }
  };

  collect(question.inputs, inputs);
  collect(question.policyRefs, policyRefs);

  if (problems.length > 0) return { status: "invalid", problems };
  if (missing.length > 0) return { status: "abstained", reason: "missing_input", fieldIds: missing };
  if (nulls.length > 0) return { status: "abstained", reason: "null_value", fieldIds: nulls };

  const payload = {
    questionId: question.questionId,
    atStage: question.atStage,
    inputs,
    policyRefs,
  };
  return { status: "projected", payload, requestDigest: digestOf(payload) };
}

state.projection_test_mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { buildPlan } from '../dist/plan.js';
import { projectQuestion, resolvePointer } from '../dist/projection.js';
import { replayPlan } from '../dist/replay.js';

const readFixture = name => JSON.parse(readFileSync(new URL(`fixtures/${name}`, import.meta.url), 'utf8'));
const twoQuestions = buildPlan(readFixture('two-questions.suite.json'), { version: 'test' });
const [qTask, qDiff] = twoQuestions.questions;

test('each question projects only its own inputs, never the union', () => {
  const state = { task: "t", diff: "d", outcome: "done", gold_label: true, expectedDiagnostics: ["QCT001"] };
  const task = projectQuestion(qTask, state);
  const diff = projectQuestion(qDiff, state);
  assert.equal(task.status, 'projected');
  assert.equal(diff.status, 'projected');
  assert.deepEqual(Object.keys(task.payload.inputs), ['task']);
  assert.deepEqual(Object.keys(diff.payload.inputs), ['diff']);
  const serialized = JSON.stringify([task.payload, diff.payload]);
  assert.ok(!serialized.includes('outcome'), serialized);
  assert.ok(!serialized.includes('gold_label'), serialized);
  assert.ok(!serialized.includes('expectedDiagnostics'), serialized);
});

test('policy references travel separately from evidence inputs', () => {
  const suite = JSON.parse(readFileSync(new URL('../examples/scope-monitor.suite.json', import.meta.url), 'utf8'));
  const plan = buildPlan(suite, { version: 'test' });
  const question = plan.questions[0];
  const outcome = projectQuestion(question, {
    task: "t", diff: "d", scope_policy: "p", final_outcome: "accepted",
  });
  assert.equal(outcome.status, 'projected');
  assert.deepEqual(Object.keys(outcome.payload.inputs), ['task', 'diff']);
  assert.deepEqual(Object.keys(outcome.payload.policyRefs), ['scope_policy']);
  assert.ok(!JSON.stringify(outcome.payload).includes('final_outcome'));
});

test('missing inputs abstain and nulls abstain unless declared nullable', () => {
  assert.deepEqual(projectQuestion(qTask, { diff: "d" }), {
    status: 'abstained', reason: 'missing_input', fieldIds: ['task'],
  });
  assert.deepEqual(projectQuestion(qTask, { task: null, diff: "d" }), {
    status: 'abstained', reason: 'null_value', fieldIds: ['task'],
  });
  const nullable = {
    ...qTask,
    inputs: [{ ...qTask.inputs[0], nullable: true }],
  };
  const outcome = projectQuestion(nullable, { task: null });
  assert.equal(outcome.status, 'projected');
  assert.equal(outcome.payload.inputs.task, null);
});

test('type violations stop the request instead of being smoothed over', () => {
  const outcome = projectQuestion(qTask, { task: 42, diff: "d" });
  assert.equal(outcome.status, 'invalid');
  assert.equal(outcome.problems[0].fieldId, 'task');
  assert.equal(outcome.problems[0].kind, 'type_mismatch');
});

test('a hand-made plan that projects a target is rejected at projection time', () => {
  const hostile = {
    ...qTask,
    inputs: [{ ...qTask.inputs[0], fieldId: 'outcome', role: 'target' }],
  };
  const outcome = projectQuestion(hostile, { outcome: "accepted" });
  assert.equal(outcome.status, 'invalid');
  assert.equal(outcome.problems[0].kind, 'target_role');
});

test('pointer resolution handles escaping, arrays, and missing paths', () => {
  const state = { a: { "b/c": [10, { "~d": 5 }] } };
  assert.deepEqual(resolvePointer(state, '/a/b~1c/1/~0d'), { found: true, value: 5 });
  assert.deepEqual(resolvePointer(state, '/a/b~1c/2'), { found: false });
  assert.deepEqual(resolvePointer(state, '/a/b~1c/01'), { found: false });
  assert.deepEqual(resolvePointer(state, '/a/missing'), { found: false });
  assert.deepEqual(resolvePointer(state, '/a/b~1c/0/x'), { found: false });
});

test('replay leaves uncovered requests not_run and records payloads', () => {
  const cases = [{ caseId: 'c1', state: { task: "t", diff: "d" } }];
  const report = replayPlan(twoQuestions, cases, [], 'test');
  assert.equal(report.summary.notRun, 2);
  assert.equal(report.summary.replayed, 0);
  assert.ok(report.results.every(result => result.requestDigest?.startsWith('sha256:')));
  assert.ok(report.results.every(result => !JSON.stringify(result.payload).includes('outcome')));
});

test('replay refuses duplicate recordings for one request digest', () => {
  const cases = [{ caseId: 'c1', state: { task: "t", diff: "d" } }];
  const first = replayPlan(twoQuestions, cases, [], 'test').results[0].requestDigest;
  assert.throws(
    () => replayPlan(twoQuestions, cases, [{ requestDigest: first, response: 1 }, { requestDigest: first, response: 2 }], 'test'),
    /duplicate recorded response/,
  );
});
